/* @lc app=leetcode id=2653 lang=kotlin */
class Solution { fun getSubarrayBeauty(nums: IntArray, k: Int, x: Int): IntArray = IntArray(101).let { f -> IntArray(nums.size - k + 1) { i -> (if (i == 0) (0 until k).forEach { f[nums[it] + 50]++ } else f[nums[i + k - 1] + 50]++.also { f[nums[i - 1] + 50]-- }).let { (0 until 50).fold(0 to 0) { (s, v), j -> if (s < x && s + f[j] >= x) x to j - 50 else (s + f[j]) to v }.second.let { if (it < 0) it else 0 } } } } }